p1_sql:
SELECT ROUND(AVG(
  -10000.0 / LN(
    (
      EXP(-10000.0 / ((em.env_metrics->'temperature'->>'max_c')::numeric + 273.15))
      + EXP(-10000.0 / ((em.env_metrics->'temperature'->>'min_c')::numeric + 273.15))
      + EXP(-10000.0 / ((em.env_metrics->'temperature'->>'avg_c')::numeric + 273.15))
    ) / 3.0
  )
)::numeric, 2) AS avg_mean_kinetic_temperature
FROM public.environmentalmonitoring AS em
WHERE (em.env_metrics->'temperature'->>'excursion_count')::numeric > 0;

p2_sql:
SELECT ROUND(STDDEV(
  -10000.0 / LN(
    (
      EXP(-10000.0 / ((em.env_metrics->'temperature'->>'max_c')::numeric + 273.15))
      + EXP(-10000.0 / ((em.env_metrics->'temperature'->>'min_c')::numeric + 273.15))
      + EXP(-10000.0 / ((em.env_metrics->'temperature'->>'avg_c')::numeric + 273.15))
    ) / 3.0
  )
)::numeric, 2) AS stddev_mean_kinetic_temperature
FROM public.environmentalmonitoring AS em
WHERE (em.env_metrics->'temperature'->>'excursion_count')::numeric > 0;
